input.content:
:root {
  --ink: #f6fbff;
  --muted: #9fb3c8;
  --cyan: #66f4ff;
  --cyan-soft: #26cfe6;
  --orange: #ff8b3d;
  --red: #ff3b5c;
  --gold: #ffd166;
  --panel: rgba(7, 11, 26, 0.86);
  --line: rgba(116, 240, 255, 0.28);
  --font-display: "Arial Black", "Segoe UI", Impact, sans-serif;
  --font-body: "Trebuchet MS", "Segoe UI", system-ui, sans-serif;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
}

* {
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

html,
body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: #04030b;
  color: var(--ink);
  font-family: var(--font-body);
  overscroll-behavior: none;
  user-select: none;
  -webkit-user-select: none;
}

body {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  height: 100dvh;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background:
    radial-gradient(120% 90% at 50% 105%, rgba(56, 22, 88, 0.55), transparent 64%),
    radial-gradient(80% 60% at 50% -10%, rgba(17, 64, 104, 0.4), transparent 60%),
    #04030b;
  touch-action: none;
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: crosshair;
}

#vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(120% 88% at 50% 50%, transparent 55%, rgba(0, 0, 0, 0.55) 100%),
    linear-gradient(to bottom, rgba(2, 2, 8, 0.32), transparent 12%, transparent 88%, rgba(2, 2, 8, 0.45));
  mix-blend-mode: multiply;
  z-index: 2;
}

#scanlines {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 3;
  opacity: 0.12;
  background: repeating-linear-gradient(
    to bottom,
    rgba(255, 255, 255, 0.11) 0px,
    rgba(255, 255, 255, 0.11) 1px,
    transparent 1px,
    transparent 3px
  );
}

.top-actions {
  position: absolute;
  z-index: 8;
  top: calc(10px + var(--safe-top));
  right: calc(10px + var(--safe-right));
  display: flex;
  gap: 8px;
  pointer-events: none;
}

.icon-btn {
  pointer-events: auto;
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid rgba(120, 235, 255, 0.32);
  background: linear-gradient(180deg, rgba(9, 20, 40, 0.82), rgba(4, 8, 20, 0.8));
  color: var(--cyan);
  font-size: 18px;
  line-height: 1;
  padding: 0;
  cursor: pointer;
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.4), 0 6px 18px rgba(0, 0, 0, 0.36);
  backdrop-filter: blur(6px);
  transition: transform 0.12s ease, border-color 0.2s ease, color 0.2s ease;
}

.icon-btn:active {
  transform: scale(0.93);
}

.icon-btn.off {
  color: #6c7b8c;
  border-color: rgba(120, 150, 170, 0.2);
}

#bombBtn {
  position: absolute;
  z-index: 8;
  right: calc(18px + var(--safe-right));
  bottom: calc(22px + var(--safe-bottom));
  width: 86px;
  height: 86px;
  border-radius: 50%;
  border: 1px solid rgba(255, 157, 70, 0.65);
  background:
    radial-gradient(circle at 38% 32%, rgba(255, 210, 140, 0.24), transparent 46%),
    radial-gradient(circle at 50% 58%, rgba(255, 96, 35, 0.22), rgba(22, 8, 6, 0.86) 72%);
  color: #ffe9c7;
  font-family: var(--font-display);
  display: none;
  place-items: center;
  cursor: pointer;
  box-shadow:
    0 0 0 6px rgba(255, 118, 45, 0.08),
    0 0 26px rgba(255, 108, 32, 0.26),
    inset 0 0 22px rgba(255, 108, 32, 0.2);
  padding: 0;
  touch-action: none;
  transition: transform 0.1s ease, opacity 0.16s ease;
}

#bombBtn.show {
  display: grid;
}

#bombBtn:active {
  transform: scale(0.92);
}

#bombBtn.empty {
  opacity: 0.35;
  border-color: rgba(160, 160, 170, 0.35);
  box-shadow: none;
}

.bomb-label {
  position: absolute;
  top: 17px;
  font-size: 15px;
  letter-spacing: 0.14em;
  text-shadow: 0 0 12px rgba(255, 150, 70, 0.8);
}

.bomb-count {
  position: absolute;
  bottom: 17px;
  font-size: 25px;
  color: #fff;
  text-shadow: 0 0 14px rgba(255, 170, 90, 0.9);
}

.bomb-ring {
  position: absolute;
  inset: 9px;
  border-radius: 50%;
  border: 1px dashed rgba(255, 190, 120, 0.34);
  animation: spin 9s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

.overlay {
  position: absolute;
  inset: 0;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: calc(18px + var(--safe-top)) calc(16px + var(--safe-right)) calc(18px + var(--safe-bottom)) calc(16px + var(--safe-left));
  opacity: 1;
  transition: opacity 0.22s ease;
}

.overlay.hidden {
  opacity: 0;
  pointer-events: none;
}

.screen {
  width: min(460px, 94vw);
  max-height: 92dvh;
  overflow-y: auto;
  scrollbar-width: none;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.screen::-webkit-scrollbar {
  display: none;
}

.card {
  width: 100%;
  position: relative;
  padding: 26px 24px 22px;
  border-radius: 20px;
  border: 1px solid rgba(120, 235, 255, 0.26);
  background:
    linear-gradient(160deg, rgba(16, 26, 54, 0.94), rgba(6, 8, 20, 0.95) 58%),
    var(--panel);
  box-shadow:
    0 0 0 1px rgba(0, 0, 0, 0.55),
    0 26px 70px rgba(0, 0, 0, 0.62),
    inset 0 1px 0 rgba(255, 255, 255, 0.07),
    0 0 60px rgba(43, 199, 230, 0.08);
  backdrop-filter: blur(10px);
  text-align: center;
  animation: cardIn 0.34s cubic-bezier(0.2, 0.9, 0.25, 1.2) both;
}

@keyframes cardIn {
  from {
    opacity: 0;
    transform: translateY(14px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.card::before,
.card::after {
  content: "";
  position: absolute;
  width: 22px;
  height: 22px;
  border-color: rgba(102, 244, 255, 0.75);
  border-style: solid;
  pointer-events: none;
}

.card::before {
  top: 8px;
  left: 8px;
  border-width: 1px 0 0 1px;
  border-radius: 8px 0 0 0;
}

.card::after {
  bottom: 8px;
  right: 8px;
  border-width: 0 1px 1px 0;
  border-radius: 0 0 8px 0;
}

.eyebrow {
  margin: 0 0 10px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.46em;
  text-transform: uppercase;
  color: var(--cyan);
  opacity: 0.78;
}

h1.title {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(38px, 12.5vw, 58px);
  line-height: 0.88;
  letter-spacing: -0.03em;
  text-transform: uppercase;
  color: #f7fdff;
  text-shadow:
    0 0 18px rgba(102, 244, 255, 0.32),
    0 4px 0 #0b1c31,
    0 5px 0 rgba(0, 0, 0, 0.7);
}

h1.title .amp {
  display: inline-block;
  color: var(--orange);
  font-size: 0.62em;
  vertical-align: 0.2em;
  margin: 0 0.02em;
  text-shadow: 0 0 24px rgba(255, 120, 45, 0.6);
}

h1.title .line2 {
  display: block;
  color: #ffc57a;
  letter-spacing: 0.06em;
  text-shadow:
    0 0 20px rgba(255, 138, 56, 0.4),
    0 4px 0 #30130c,
    0 5px 0 rgba(0, 0, 0, 0.7);
}

.tagline {
  margin: 14px 0 0;
  font-size: 13px;
  line-height: 1.55;
  color: #b9c9da;
  letter-spacing: 0.02em;
}

.boss-chips {
  display: flex;
  gap: 8px;
  justify-content: center;
  margin: 18px 0 4px;
}

.chip {
  flex: 1;
  min-width: 0;
  padding: 10px 8px;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.035);
  text-align: left;
}

.chip .n {
  display: block;
  font-size: 9px;
  letter-spacing: 0.16em;
  color: #7d93a8;
  font-weight: 700;
}

.chip .v {
  display: block;
  margin-top: 4px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.03em;
}

.chip.dragon .v {
  color: #ff9068;
}

.chip.robot .v {
  color: #7fe6ff;
}

button.primary {
  width: 100%;
  margin: 20px 0 0;
  min-height: 56px;
  border-radius: 12px;
  border: 1px solid rgba(255, 210, 140, 0.6);
  background:
    linear-gradient(180deg, rgba(255, 166, 71, 0.98), rgba(231, 88, 30, 0.98));
  color: #1b0803;
  font-family: var(--font-display);
  font-size: 18px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  cursor: pointer;
  box-shadow:
    0 8px 0 #772208,
    0 12px 28px rgba(255, 94, 24, 0.28),
    inset 0 1px 0 rgba(255, 255, 255, 0.55);
  transition: transform 0.1s ease, box-shadow 0.1s ease, filter 0.18s ease;
  touch-action: manipulation;
}

button.primary:active {
  transform: translateY(5px);
  box-shadow:
    0 3px 0 #772208,
    0 6px 14px rgba(255, 94, 24, 0.24),
    inset 0 1px 0 rgba(255, 255, 255, 0.45);
}

button.primary.blue {
  border-color: rgba(150, 245, 255, 0.55);
  background: linear-gradient(180deg, #61ecff, #18a6c6);
  color: #02151c;
  box-shadow:
    0 8px 0 #0a5a6e,
    0 12px 28px rgba(49, 208, 236, 0.24),
    inset 0 1px 0 rgba(255, 255, 255, 0.5);
}

button.ghost {
  width: 100%;
  margin-top: 10px;
  min-height: 46px;
  border-radius: 10px;
  border: 1px solid rgba(140, 200, 230, 0.24);
  background: rgba(255, 255, 255, 0.045);
  color: #d9e8f5;
  font-family: var(--font-body);
  font-weight: 700;
  font-size: 13px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  cursor: pointer;
}

button.ghost:active {
  background: rgba(255, 255, 255, 0.11);
}

.howto {
  margin: 18px 0 0;
  display: grid;
  gap: 7px;
  font-size: 12px;
  color: #9fb2c6;
  text-align: left;
}

.howto div {
  display: flex;
  gap: 10px;
  align-items: baseline;
}

.howto b {
  color: #d9ecfa;
  font-weight: 700;
}

.howto .k {
  flex: 0 0 auto;
  min-width: 22px;
  text-align: center;
  color: var(--cyan);
  font-size: 14px;
}

.fineprint {
  margin: 16px 0 0;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #61758a;
}

.scoreboard {
  display: flex;
  justify-content: center;
  gap: 26px;
  margin: 18px 0 4px;
}

.stat {
  text-align: center;
}

.stat .label {
  font-size: 9px;
  letter-spacing: 0.22em;
  color: #7e93a9;
  font-weight: 700;
}

.stat .value {
  margin-top: 3px;
  font-family: var(--font-display);
  font-size: 28px;
  color: #fff;
  letter-spacing: 0.02em;
}

.stat .value.orange {
  color: var(--gold);
  text-shadow: 0 0 16px rgba(255, 188, 84, 0.4);
}

.result-tag {
  margin: 2px 0 0;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--cyan);
  opacity: 0.8;
}

.result-tag.bad {
  color: var(--red);
}

.result-sub {
  margin: 12px 0 0;
  font-size: 12.5px;
  line-height: 1.55;
  color: #a6b9ca;
}

.pause-badge {
  display: inline-grid;
  place-items: center;
  width: 52px;
  height: 52px;
  margin: 0 auto 14px;
  border-radius: 50%;
  border: 1px solid rgba(102, 244, 255, 0.35);
  background: rgba(102, 244, 255, 0.08);
  color: var(--cyan);
  font-size: 22px;
}

.rotate-hint {
  position: absolute;
  z-index: 7;
  left: 50%;
  bottom: calc(16px + var(--safe-bottom));
  transform: translateX(-50%);
  display: none;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  border-radius: 999px;
  background: rgba(5, 9, 20, 0.78);
  border: 1px solid rgba(120, 235, 255, 0.22);
  color: #8fa5b8;
  font-size: 10px;
  letter-spacing: 0.08em;
  white-space: nowrap;
  pointer-events: none;
  backdrop-filter: blur(6px);
}

@media (orientation: landscape) and (max-height: 520px) {
  .rotate-hint {
    display: flex;
  }

  h1.title {
    font-size: 34px;
  }

  .card {
    padding: 18px 20px 16px;
  }

  .howto {
    display: none;
  }

  .boss-chips {
    margin: 12px 0 0;
  }

  #bombBtn {
    width: 74px;
    height: 74px;
  }
}

@media (max-height: 700px) {
  .card {
    padding: 20px 20px 18px;
  }

  h1.title {
    font-size: clamp(34px, 11vw, 50px);
  }

  .howto {
    margin-top: 14px;
  }
}

// Tiny WebAudio synth: all SFX and music are generated at runtime.
export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.musicGain = null;
    this.muted = false;
    this.musicTimer = null;
    this.musicOn = false;
    this.stage = 1;
    this.step = 0;
    this.nextNote = 0;
    this.lastShoot = 0;
    this.lastHit = 0;
    this._noise = null;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.62;
    this.master.connect(this.ctx.destination);
    this.musicGain = this.ctx.createGain();
    this.musicGain.gain.value = 0.0;
    this.musicGain.connect(this.master);
    this._makeNoise();
  }

  _makeNoise() {
    const len = Math.floor(this.ctx.sampleRate * 1.2);
    const buffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    this._noise = buffer;
  }

  setMuted(muted) {
    this.muted = muted;
    if (this.master) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime);
      this.master.gain.setTargetAtTime(muted ? 0 : 0.62, this.ctx.currentTime, 0.03);
    }
  }

  tone(freq, dur, type = 'sine', vol = 0.1, slideTo = null, delay = 0, dest = null) {
    if (!this.ctx) return;
    const t0 = this.ctx.currentTime + delay;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = type;
    o.frequency.setValueAtTime(Math.max(20, freq), t0);
    if (slideTo) o.frequency.exponentialRampToValueAtTime(Math.max(20, slideTo), t0 + dur);
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, vol), t0 + 0.008);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    o.connect(g);
    g.connect(dest || this.master);
    o.start(t0);
    o.stop(t0 + dur + 0.04);
  }

  noise(dur, vol = 0.12, filterType = 'lowpass', freq = 1200, freqTo = null, delay = 0, dest = null) {
    if (!this.ctx || !this._noise) return;
    const t0 = this.ctx.currentTime + delay;
    const src = this.ctx.createBufferSource();
    src.buffer = this._noise;
    src.loop = true;
    const filter = this.ctx.createBiquadFilter();
    filter.type = filterType;
    filter.frequency.setValueAtTime(freq, t0);
    if (freqTo) filter.frequency.exponentialRampToValueAtTime(Math.max(30, freqTo), t0 + dur);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, vol), t0 + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    src.connect(filter);
    filter.connect(g);
    g.connect(dest || this.master);
    src.start(t0);
    src.stop(t0 + dur + 0.03);
  }

  shoot() {
    const now = performance.now();
    if (now - this.lastShoot < 58) return;
    this.lastShoot = now;
    this.tone(1250, 0.05, 'square', 0.018, 640);
  }

  enemyShoot() {
    this.tone(250, 0.09, 'sawtooth', 0.022, 130);
  }

  rocket() {
    this.noise(0.45, 0.1, 'bandpass', 950, 210);
    this.tone(150, 0.36, 'sawtooth', 0.05, 55);
  }

  hit() {
    const now = performance.now();
    if (now - this.lastHit < 34) return;
    this.lastHit = now;
    this.tone(420, 0.04, 'square', 0.02, 190);
  }

  explode(big = 0) {
    this.noise(0.34 + big * 0.25, 0.16 + big * 0.08, 'lowpass', 1600, 110);
    this.tone(110, 0.3 + big * 0.2, 'sine', 0.11 + big * 0.05, 34);
    if (big > 0.5) this.tone(62, 0.65, 'triangle', 0.12, 24, 0.04);
  }

  playerHit() {
    this.noise(0.4, 0.2, 'lowpass', 2200, 120);
    this.tone(300, 0.5, 'sawtooth', 0.1, 45);
  }

  powerup() {
    this.tone(660, 0.09, 'triangle', 0.06, 990);
    this.tone(990, 0.1, 'triangle', 0.055, 1320, 0.07);
    this.tone(1320, 0.14, 'sine', 0.05, 1760, 0.14);
  }

  bomb() {
    this.noise(0.9, 0.24, 'lowpass', 2400, 70);
    this.tone(160, 0.8, 'sawtooth', 0.12, 28);
    this.tone(1200, 0.3, 'sine', 0.05, 240);
  }

  warning() {
    for (let i = 0; i < 4; i++) {
      this.tone(480, 0.22, 'square', 0.05, 740, i * 0.42);
      this.tone(740, 0.22, 'square', 0.04, 480, i * 0.42 + 0.22);
    }
    this.noise(1.8, 0.035, 'bandpass', 500, 260);
  }

  roar() {
    this.noise(1.1, 0.18, 'lowpass', 900, 90);
    this.tone(82, 1.05, 'sawtooth', 0.09, 36);
    this.tone(55, 1.15, 'triangle', 0.1, 30, 0.03);
  }

  beam() {
    this.noise(1.4, 0.14, 'bandpass', 1800, 400);
    this.tone(240, 1.2, 'sawtooth', 0.045, 90);
  }

  laser() {
    this.tone(1800, 0.35, 'sawtooth', 0.05, 540);
    this.noise(0.9, 0.08, 'highpass', 1400, 600);
  }

  stageClear() {
    const notes = [523, 659, 784, 1046];
    notes.forEach((n, i) => this.tone(n, 0.18, 'triangle', 0.07, n * 1.02, i * 0.12));
    this.noise(0.5, 0.08, 'lowpass', 1800, 200, 0.3);
  }

  victory() {
    const notes = [523, 659, 784, 1046, 1318];
    notes.forEach((n, i) => this.tone(n, 0.32, 'triangle', 0.075, n, i * 0.14));
    this.tone(261, 1.2, 'sine', 0.08, 261, 0.05);
    this.noise(0.8, 0.1, 'lowpass', 2400, 240, 0.5);
  }

  ui() {
    this.tone(720, 0.06, 'triangle', 0.045, 1080);
  }

  startMusic(stage) {
    this.init();
    if (!this.ctx) return;
    this.stopMusic();
    this.stage = stage;
    this.musicOn = true;
    this.step = 0;
    this.nextNote = this.ctx.currentTime + 0.12;
    this.musicGain.gain.cancelScheduledValues(this.ctx.currentTime);
    this.musicGain.gain.setTargetAtTime(0.55, this.ctx.currentTime, 0.4);
    this.musicTimer = setInterval(() => this._schedule(), 110);
  }

  stopMusic() {
    this.musicOn = false;
    if (this.musicTimer) clearInterval(this.musicTimer);
    this.musicTimer = null;
    if (this.musicGain && this.ctx) {
      this.musicGain.gain.cancelScheduledValues(this.ctx.currentTime);
      this.musicGain.gain.setTargetAtTime(0.0001, this.ctx.currentTime, 0.15);
    }
  }

  pauseMusic(paused) {
    if (!this.musicOn || !this.ctx) return;
    this.musicGain.gain.setTargetAtTime(paused ? 0.12 : 0.55, this.ctx.currentTime, 0.12);
  }

  _schedule() {
    if (!this.ctx || !this.musicOn) return;
    const ahead = this.ctx.currentTime + 0.3;
    while (this.nextNote < ahead) {
      this._playStep(this.step, this.nextNote);
      this.step++;
      this.nextNote += 0.24;
    }
  }

  _playStep(step, time) {
    const stage = this.stage;
    const roots = stage === 1 ? [55, 65.41, 58.27, 73.42] : [49, 58.27, 65.41, 46.25];
    const chords = stage === 1
      ? [[220, 261.63, 329.63], [261.63, 329.63, 392], [233.08, 293.66, 349.23], [293.66, 349.23, 440]]
      : [[196, 233.08, 293.66], [233.08, 293.66, 349.23], [261.63, 311.13, 392], [185, 233.08, 277.18]];
    const root = roots[Math.floor(step / 8) % roots.length];
    const chord = chords[Math.floor(step / 8) % chords.length];
    const t = time - this.ctx.currentTime;
    if (t < -0.1) return;
    if (step % 8 === 0) {
      this.tone(root, 1.6, 'sine', 0.055, root * 0.99, Math.max(0, t), this.musicGain);
      this.tone(root * 2, 1.2, 'triangle', 0.022, root * 2, Math.max(0, t), this.musicGain);
    }
    if (step % 4 === 0) {
      this.noise(0.09, 0.012, 'highpass', 4800, 2400, Math.max(0, t), this.musicGain);
    }
    if (step % 2 === 1) {
      const note = chord[(Math.floor(step / 2) + step) % chord.length] * (stage === 1 ? 2 : 1.5);
      this.tone(note, 0.16, 'triangle', 0.014, note, Math.max(0, t), this.musicGain);
    }
    if (stage === 2 && step % 2 === 0) {
      this.noise(0.05, 0.009, 'bandpass', 7000, 4000, Math.max(0, t), this.musicGain);
    }
  }
}

// All artwork is drawn procedurally with Canvas 2D — no external assets.
export const TAU = Math.PI * 2;
export const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
export const lerp = (a, b, t) => a + (b - a) * t;
export const rand = (a, b) => a + Math.random() * (b - a);

function mulberry32(seed) {
  return function () {
    let t = (seed += 0x6d2b79f5);
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function roundedRect(ctx, x, y, w, h, r) {
  const rr = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.arcTo(x + w, y, x + w, y + h, rr);
  ctx.arcTo(x + w, y + h, x, y + h, rr);
  ctx.arcTo(x, y + h, x, y, rr);
  ctx.arcTo(x, y, x + w, y, rr);
  ctx.closePath();
}

function cloudSprite(tint) {
  const c = document.createElement('canvas');
  c.width = 240;
  c.height = 130;
  const g = c.getContext('2d');
  const puffs = [
    [70, 78, 42, 0.55],
    [112, 62, 54, 0.7],
    [162, 80, 44, 0.55],
    [118, 92, 60, 0.4],
    [38, 92, 30, 0.36],
    [196, 96, 32, 0.32],
  ];
  g.globalCompositeOperation = 'lighter';
  for (const [x, y, r, a] of puffs) {
    const grad = g.createRadialGradient(x, y, r * 0.08, x, y, r);
    grad.addColorStop(0, `rgba(${tint[0]},${tint[1]},${tint[2]},${a})`);
    grad.addColorStop(0.55, `rgba(${tint[0]},${tint[1]},${tint[2]},${a * 0.42})`);
    grad.addColorStop(1, `rgba(${tint[0]},${tint[1]},${tint[2]},0)`);
    g.fillStyle = grad;
    g.beginPath();
    g.arc(x, y, r, 0, TAU);
    g.fill();
  }
  return c;
}

export function createBackdrop(W, H, stage) {
  const rnd = mulberry32(stage === 1 ? 9182 : 55127);
  const bd = {
    stage,
    W,
    H,
    scroll: 0,
    stars: [],
    clouds: [],
    buildings: [],
    rain: [],
    glints: [],
    cloudSprites: [],
    moon: { x: W * (stage === 1 ? 0.74 : 0.24), y: H * 0.2, r: stage === 1 ? 88 : 62 },
  };
  const starCount = stage === 1 ? 70 : 115;
  for (let i = 0; i < starCount; i++) {
    bd.stars.push({
      x: rnd() * W,
      y: rnd() * H,
      r: 0.5 + rnd() * 1.5,
      a: 0.25 + rnd() * 0.6,
      tw: rnd() * TAU,
      speed: 2 + rnd() * 8,
    });
  }
  bd.cloudSprites = [
    cloudSprite(stage === 1 ? [255, 138, 120] : [88, 175, 210]),
    cloudSprite(stage === 1 ? [210, 110, 180] : [120, 120, 220]),
    cloudSprite(stage === 1 ? [255, 190, 140] : [70, 220, 205]),
  ];
  for (let i = 0; i < 9; i++) {
    bd.clouds.push({
      x: rnd() * W,
      y: rnd() * H,
      s: 0.55 + rnd() * 1.15,
      a: stage === 1 ? 0.1 + rnd() * 0.24 : 0.05 + rnd() * 0.12,
      sp: 9 + rnd() * 26,
      sprite: Math.floor(rnd() * 3),
    });
  }
  if (stage === 2) {
    for (let i = 0; i < 16; i++) {
      const depth = 0.35 + rnd() * 0.9;
      const w = 50 + rnd() * 110;
      const b = {
        x: rnd() * (W + 160) - 80,
        y: rnd() * H,
        w,
        h: 80 + rnd() * 170,
        depth,
        sp: 14 + depth * 34,
        hue: rnd() > 0.5 ? 'cyan' : 'pink',
        windows: [],
      };
      const cols = Math.max(2, Math.floor(w / 18));
      const rows = Math.max(3, Math.floor(b.h / 20));
      for (let c = 0; c < cols; c++) {
        for (let r = 0; r < rows; r++) {
          if (rnd() > 0.62) {
            b.windows.push({
              x: 7 + c * ((w - 14) / cols),
              y: 10 + r * ((b.h - 20) / rows),
              w: 3 + rnd() * 3,
              h: 2 + rnd() * 3,
              a: 0.15 + rnd() * 0.55,
              blink: rnd() > 0.85,
            });
          }
        }
      }
      bd.buildings.push(b);
    }
    bd.buildings.sort((a, b) => a.depth - b.depth);
    for (let i = 0; i < 80; i++) {
      bd.rain.push({
        x: rnd() * (W + 100) - 50,
        y: rnd() * H,
        len: 8 + rnd() * 18,
        sp: 420 + rnd() * 320,
        a: 0.08 + rnd() * 0.22,
      });
    }
  }
  for (let i = 0; i < 26; i++) {
    bd.glints.push({
      x: rnd() * W,
      y: rnd() * H,
      r: 1 + rnd() * 2.6,
      sp: 12 + rnd() * 28,
      ph: rnd() * TAU,
      a: 0.15 + rnd() * 0.4,
    });
  }
  return bd;
}

export function updateBackdrop(bd, dt, W, H) {
  bd.W = W;
  bd.H = H;
  bd.scroll += dt * 16;
  for (const s of bd.stars) {
    s.y += s.speed * dt;
    if (s.y > H + 4) {
      s.y = -6;
      s.x = Math.random() * W;
    }
  }
  for (const c of bd.clouds) {
    c.y += c.sp * dt;
    c.x += Math.sin(bd.scroll * 0.01 + c.y * 0.01) * 3 * dt;
    if (c.y > H + 100) {
      c.y = -120;
      c.x = Math.random() * W;
    }
  }
  for (const b of bd.buildings) {
    b.y += b.sp * dt;
    if (b.y > H + b.h + 20) {
      b.y = -b.h - Math.random() * 160;
      b.x = Math.random() * (W + 160) - 80;
    }
  }
  for (const r of bd.rain) {
    r.y += r.sp * dt;
    r.x -= r.sp * 0.16 * dt;
    if (r.y > H + 20) {
      r.y = -20;
      r.x = Math.random() * (W + 120) - 30;
    }
    if (r.x < -30) r.x = W + 20;
  }
  for (const g of bd.glints) {
    g.y += g.sp * dt;
    if (g.y > H + 6) {
      g.y = -6;
      g.x = Math.random() * W;
    }
  }
}

export function drawBackdrop(ctx, bd, W, H, time) {
  const stage = bd.stage;
  // Sky
  const sky = ctx.createLinearGradient(0, 0, 0, H);
  if (stage === 1) {
    sky.addColorStop(0, '#060417');
    sky.addColorStop(0.32, '#1a0a31');
    sky.addColorStop(0.62, '#3f123f');
    sky.addColorStop(0.84, '#75263f');
    sky.addColorStop(1, '#b04a3d');
  } else {
    sky.addColorStop(0, '#02040d');
    sky.addColorStop(0.4, '#05101d');
    sky.addColorStop(0.75, '#071a29');
    sky.addColorStop(1, '#0a2634');
  }
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, W, H);

  // Moon / distant orb
  const m = bd.moon;
  const mg = ctx.createRadialGradient(m.x, m.y, 2, m.x, m.y, m.r * 2.4);
  if (stage === 1) {
    mg.addColorStop(0, 'rgba(255,214,170,0.95)');
    mg.addColorStop(0.18, 'rgba(255,178,130,0.55)');
    mg.addColorStop(0.55, 'rgba(255,120,90,0.12)');
    mg.addColorStop(1, 'rgba(255,100,80,0)');
  } else {
    mg.addColorStop(0, 'rgba(170,240,255,0.8)');
    mg.addColorStop(0.2, 'rgba(90,200,240,0.3)');
    mg.addColorStop(0.55, 'rgba(60,160,220,0.08)');
    mg.addColorStop(1, 'rgba(40,120,200,0)');
  }
  ctx.fillStyle = mg;
  ctx.beginPath();
  ctx.arc(m.x, m.y, m.r * 2.4, 0, TAU);
  ctx.fill();
  ctx.fillStyle = stage === 1 ? 'rgba(255,206,158,0.36)' : 'rgba(150,225,245,0.2)';
  ctx.beginPath();
  ctx.arc(m.x, m.y, m.r * 0.62, 0, TAU);
  ctx.fill();

  // Stars
  for (const s of bd.stars) {
    const tw = 0.55 + 0.45 * Math.sin(time * 1.6 + s.tw);
    ctx.globalAlpha = s.a * tw;
    ctx.fillStyle = stage === 1 ? '#ffe6c8' : '#c8f6ff';
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.r, 0, TAU);
    ctx.fill();
  }
  ctx.globalAlpha = 1;

  // Distant glow near bottom
  const glow = ctx.createRadialGradient(W / 2, H * 1.05, 10, W / 2, H * 1.05, H * 0.62);
  glow.addColorStop(0, stage === 1 ? 'rgba(255,108,60,0.25)' : 'rgba(32,180,220,0.16)');
  glow.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = glow;
  ctx.fillRect(0, 0, W, H);

  if (stage === 2) {
    // Rooftops / skyline scrolling beneath
    for (const b of bd.buildings) {
      ctx.save();
      ctx.globalAlpha = 0.5 + b.depth * 0.28;
      const grad = ctx.createLinearGradient(0, b.y, 0, b.y + b.h);
      grad.addColorStop(0, '#0b1b2a');
      grad.addColorStop(0.6, '#061019');
      grad.addColorStop(1, '#03080f');
      ctx.fillStyle = grad;
      ctx.fillRect(b.x, b.y, b.w, b.h);
      ctx.strokeStyle = b.hue === 'cyan' ? 'rgba(82,226,255,0.22)' : 'rgba(255,96,180,0.2)';
      ctx.lineWidth = 1;
      ctx.strokeRect(b.x + 0.5, b.y + 0.5, b.w - 1, b.h - 1);
      // roof edge light
      ctx.fillStyle = b.hue === 'cyan' ? 'rgba(110,240,255,0.4)' : 'rgba(255,130,200,0.36)';
      ctx.fillRect(b.x + 3, b.y + 2, b.w - 6, 1.4);
      // vents
      ctx.fillStyle = 'rgba(0,0,0,0.3)';
      ctx.fillRect(b.x + b.w * 0.14, b.y + 11, b.w * 0.2, 5);
      ctx.fillRect(b.x + b.w * 0.62, b.y + b.h - 18, b.w * 0.16, 6);
      for (const w of b.windows) {
        let a = w.a;
        if (w.blink) a *= 0.6 + 0.4 * Math.sin(time * 3 + w.x * 0.5);
        ctx.globalAlpha = a * (0.5 + b.depth * 0.3);
        ctx.fillStyle = b.hue === 'cyan' ? '#8ff4ff' : '#ff9edb';
        ctx.fillRect(b.x + w.x, b.y + w.y, w.w, w.h);
      }
      ctx.restore();
    }
    // wet-road light streaks
    ctx.save();
    for (const g of bd.glints) {
      ctx.globalAlpha = g.a * (0.4 + 0.6 * Math.sin(time * 1.4 + g.ph));
      ctx.fillStyle = '#7fe8ff';
      ctx.fillRect(g.x, g.y, 1.4, 12 + g.r * 4);
    }
    ctx.restore();
    // rain
    ctx.save();
    ctx.strokeStyle = 'rgba(150,220,255,0.6)';
    ctx.lineWidth = 1;
    for (const r of bd.rain) {
      ctx.globalAlpha = r.a;
      ctx.beginPath();
      ctx.moveTo(r.x, r.y);
      ctx.lineTo(r.x - r.len * 0.16, r.y + r.len);
      ctx.stroke();
    }
    ctx.restore();
  }

  // Clouds
  for (const c of bd.clouds) {
    const sprite = bd.cloudSprites[c.sprite];
    ctx.save();
    ctx.globalAlpha = c.a;
    ctx.globalCompositeOperation = 'lighter';
    const w = 240 * c.s;
    const h = 130 * c.s;
    ctx.drawImage(sprite, c.x - w / 2, c.y - h / 2, w, h);
    ctx.restore();
  }

  // Floating embers / glints
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (const g of bd.glints) {
    const a = g.a * (0.5 + 0.5 * Math.sin(time * 2 + g.ph));
    ctx.globalAlpha = a;
    ctx.fillStyle = stage === 1 ? '#ffb070' : '#6fe6ff';
    ctx.beginPath();
    ctx.arc(g.x + Math.sin(time * 0.7 + g.ph) * 5, g.y, g.r, 0, TAU);
    ctx.fill();
  }
  ctx.restore();

  // Soft bottom haze
  const haze = ctx.createLinearGradient(0, H * 0.6, 0, H);
  haze.addColorStop(0, 'rgba(0,0,0,0)');
  haze.addColorStop(1, stage === 1 ? 'rgba(255,110,60,0.08)' : 'rgba(20,190,220,0.07)');
  ctx.fillStyle = haze;
  ctx.fillRect(0, H * 0.6, W, H * 0.4);
}

// ---------------------------------------------------------------- player
export function drawPlayer(ctx, p, t) {
  const s = p.scale || 1;
  ctx.save();
  ctx.translate(p.x, p.y);
  ctx.rotate(p.tilt || 0);
  ctx.scale(s, s);

  // engine glow
  ctx.globalCompositeOperation = 'lighter';
  const eg = ctx.createRadialGradient(0, 26, 1, 0, 26, 34);
  eg.addColorStop(0, 'rgba(120,245,255,0.5)');
  eg.addColorStop(0.45, 'rgba(50,190,255,0.16)');
  eg.addColorStop(1, 'rgba(20,120,255,0)');
  ctx.fillStyle = eg;
  ctx.beginPath();
  ctx.arc(0, 26, 34, 0, TAU);
  ctx.fill();

  for (const side of [-1, 1]) {
    const flick = 0.72 + 0.28 * Math.sin(t * 41 + side * 2.1) + 0.08 * Math.sin(t * 77);
    const fg = ctx.createLinearGradient(0, 14, 0, 40);
    fg.addColorStop(0, 'rgba(230,255,255,0.95)');
    fg.addColorStop(0.3, 'rgba(90,235,255,0.85)');
    fg.addColorStop(0.7, 'rgba(40,130,255,0.35)');
    fg.addColorStop(1, 'rgba(20,60,255,0)');
    ctx.fillStyle = fg;
    ctx.beginPath();
    ctx.moveTo(side * 10 - 4.5, 15);
    ctx.quadraticCurveTo(side * 10 - 1, 26 + 16 * flick, side * 10, 30 + 18 * flick);
    ctx.quadraticCurveTo(side * 10 + 1, 26 + 16 * flick, side * 10 + 4.5, 15);
    ctx.closePath();
    ctx.fill();
  }
  ctx.globalCompositeOperation = 'source-over';

  // wings
  for (const side of [-1, 1]) {
    ctx.save();
    ctx.translate(0, 4);
    ctx.scale(side, 1);
    const wg = ctx.createLinearGradient(4, -6, 32, 24);
    wg.addColorStop(0, '#173d5e');
    wg.addColorStop(0.55, '#0b243a');
    wg.addColorStop(1, '#071726');
    ctx.fillStyle = wg;
    ctx.strokeStyle = 'rgba(96,235,255,0.72)';
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(5, -9);
    ctx.lineTo(30, 10);
    ctx.lineTo(37, 22);
    ctx.lineTo(23, 18);
    ctx.lineTo(19, 25);
    ctx.lineTo(10, 13);
    ctx.lineTo(5, 19);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    // wing panel line
    ctx.strokeStyle = 'rgba(96,235,255,0.3)';
    ctx.lineWidth = 0.8;
    ctx.beginPath();
    ctx.moveTo(9, 0);
    ctx.lineTo(26, 16);
    ctx.stroke();
    // missile pod
    ctx.fillStyle = '#33506a';
    ctx.fillRect(22, 7, 3.4, 10);
    ctx.fillStyle = '#ff9d4d';
    ctx.fillRect(22, 6, 3.4, 2.4);
    ctx.restore();
  }

  // body
  const bg = ctx.createLinearGradient(0, -34, 0, 26);
  bg.addColorStop(0, '#f4feff');
  bg.addColorStop(0.24, '#bdeeff');
  bg.addColorStop(0.55, '#4f96bb');
  bg.addColorStop(0.82, '#1a3a55');
  bg.addColorStop(1, '#0a1a2a');
  ctx.fillStyle = bg;
  ctx.strokeStyle = 'rgba(160,250,255,0.85)';
  ctx.lineWidth = 1.3;
  ctx.beginPath();
  ctx.moveTo(0, -34);
  ctx.quadraticCurveTo(6, -20, 8, -6);
  ctx.quadraticCurveTo(10, 10, 7, 24);
  ctx.lineTo(-7, 24);
  ctx.quadraticCurveTo(-10, 10, -8, -6);
  ctx.quadraticCurveTo(-6, -20, 0, -34);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();

  // center spine
  ctx.fillStyle = 'rgba(240,255,255,0.72)';
  ctx.beginPath();
  ctx.moveTo(0, -30);
  ctx.lineTo(2.2, -8);
  ctx.lineTo(1.6, 14);
  ctx.lineTo(-1.6, 14);
  ctx.lineTo(-2.2, -8);
  ctx.closePath();
  ctx.fill();

  // cockpit
  const cg = ctx.createLinearGradient(0, -16, 0, 2);
  cg.addColorStop(0, '#e8ffff');
  cg.addColorStop(0.35, '#5aeaff');
  cg.addColorStop(1, '#06283c');
  ctx.fillStyle = cg;
  ctx.beginPath();
  ctx.ellipse(0, -7, 4.6, 9.2, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(6,25,40,0.7)';
  ctx.lineWidth = 1;
  ctx.stroke();

  // nose light
  ctx.globalCompositeOperation = 'lighter';
  ctx.fillStyle = 'rgba(160,250,255,0.9)';
  ctx.beginPath();
  ctx.arc(0, -31, 2.2, 0, TAU);
  ctx.fill();
  ctx.globalCompositeOperation = 'source-over';

  // tail fins
  for (const side of [-1, 1]) {
    ctx.fillStyle = '#0c2438';
    ctx.strokeStyle = 'rgba(96,235,255,0.5)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(side * 5, 14);
    ctx.lineTo(side * 14, 26);
    ctx.lineTo(side * 11, 28);
    ctx.lineTo(side * 3, 21);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
  }

  ctx.restore();

  // invulnerability shield
  if (p.invuln > 0) {
    const a = 0.25 + 0.35 * Math.abs(Math.sin(t * 7));
    ctx.save();
    ctx.translate(p.x, p.y);
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = `rgba(110,240,255,${a})`;
    ctx.lineWidth = 1.4;
    ctx.setLineDash([7, 8]);
    ctx.lineDashOffset = -t * 36;
    ctx.beginPath();
    ctx.arc(0, 0, 32 + Math.sin(t * 5) * 2, 0, TAU);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.restore();
  }
}

// ---------------------------------------------------------------- enemies
export function drawEnemy(ctx, e, t) {
  const s = e.size || 1;
  ctx.save();
  ctx.translate(e.x, e.y);
  ctx.scale(s, s);
  if (e.type === 'imp') {
    const flap = Math.sin(t * 10 + e.seed) * 0.5;
    // wings
    for (const side of [-1, 1]) {
      ctx.save();
      ctx.scale(side, 1);
      ctx.rotate(flap * 0.18);
      ctx.fillStyle = 'rgba(116,22,48,0.92)';
      ctx.strokeStyle = 'rgba(255,104,110,0.55)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(6, -4);
      ctx.quadraticCurveTo(21, -18, 29, -3);
      ctx.quadraticCurveTo(22, 5, 16, 3);
      ctx.quadraticCurveTo(14, 12, 6, 7);
      ctx.closePath();
      ctx.fill();
      ctx.stroke();
      ctx.restore();
    }
    // body
    const g = ctx.createLinearGradient(0, -18, 0, 18);
    g.addColorStop(0, '#ff6d63');
    g.addColorStop(0.4, '#9a1d3c');
    g.addColorStop(1, '#39091b');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.ellipse(0, 0, 9, 15, 0, 0, TAU);
    ctx.fill();
    // head
    ctx.fillStyle = '#c23550';
    ctx.beginPath();
    ctx.ellipse(0, -10, 8, 7, 0, 0, TAU);
    ctx.fill();
    // horns
    ctx.fillStyle = '#ffd8b0';
    for (const side of [-1, 1]) {
      ctx.beginPath();
      ctx.moveTo(side * 5, -15);
      ctx.lineTo(side * 9, -24);
      ctx.lineTo(side * 1.5, -16);
      ctx.closePath();
      ctx.fill();
    }
    // eyes
    ctx.globalCompositeOperation = 'lighter';
    ctx.fillStyle = '#ffe25e';
    for (const side of [-1, 1]) {
      ctx.beginPath();
      ctx.ellipse(side * 3.4, -11, 1.9, 2.6, 0, 0, TAU);
      ctx.fill();
    }
    ctx.fillStyle = 'rgba(255,120,60,0.8)';
    ctx.beginPath();
    ctx.arc(0, 11, 2.4, 0, TAU);
    ctx.fill();
    ctx.globalCompositeOperation = 'source-over';
  } else if (e.type === 'diver') {
    ctx.rotate(e.angle || 0);
    ctx.globalCompositeOperation = 'lighter';
    const trail = ctx.createLinearGradient(0, -6, 0, 34);
    trail.addColorStop(0, 'rgba(255,170,60,0.8)');
    trail.addColorStop(1, 'rgba(255,60,30,0)');
    ctx.fillStyle = trail;
    ctx.beginPath();
    ctx.moveTo(-4, 3);
    ctx.lineTo(4, 3);
    ctx.lineTo(0, 36);
    ctx.closePath();
    ctx.fill();
    ctx.globalCompositeOperation = 'source-over';
    const g = ctx.createLinearGradient(0, -20, 0, 12);
    g.addColorStop(0, '#ffe6a8');
    g.addColorStop(0.3, '#ff8a3c');
    g.addColorStop(1, '#6b160f');
    ctx.fillStyle = g;
    ctx.strokeStyle = '#ffd08a';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(0, -21);
    ctx.lineTo(12, 4);
    ctx.lineTo(5, 2);
    ctx.lineTo(0, 10);
    ctx.lineTo(-5, 2);
    ctx.lineTo(-12, 4);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = '#fff8dd';
    ctx.beginPath();
    ctx.arc(0, -9, 2.2, 0, TAU);
    ctx.fill();
  } else if (e.type === 'drone') {
    const bob = Math.sin(t * 3 + e.seed) * 2;
    ctx.translate(0, bob);
    // side rotors
    ctx.fillStyle = 'rgba(40,120,160,0.5)';
    for (const side of [-1, 1]) {
      ctx.beginPath();
      ctx.ellipse(side * 17, 0, 8, 3, 0, 0, TAU);
      ctx.fill();
    }
    const g = ctx.createLinearGradient(0, -12, 0, 12);
    g.addColorStop(0, '#3b6f86');
    g.addColorStop(0.5, '#122d40');
    g.addColorStop(1, '#050f18');
    ctx.fillStyle = g;
    ctx.strokeStyle = 'rgba(110,235,255,0.7)';
    ctx.lineWidth = 1.1;
    ctx.beginPath();
    ctx.arc(0, 0, 14, 0, TAU);
    ctx.fill();
    ctx.stroke();
    // dome
    ctx.fillStyle = 'rgba(90,240,255,0.3)';
    ctx.beginPath();
    ctx.arc(0, -3, 8, Math.PI, TAU);
    ctx.fill();
    // eye
    ctx.globalCompositeOperation = 'lighter';
    ctx.fillStyle = '#ff5b4d';
    ctx.beginPath();
    ctx.arc(0, 1, 3, 0, TAU);
    ctx.fill();
    ctx.fillStyle = 'rgba(255,80,70,0.25)';
    ctx.beginPath();
    ctx.arc(0, 1, 8, 0, TAU);
    ctx.fill();
    ctx.globalCompositeOperation = 'source-over';
  } else if (e.type === 'gunship') {
    const g = ctx.createLinearGradient(0, -22, 0, 22);
    g.addColorStop(0, '#4b6072');
    g.addColorStop(0.5, '#1a2b3a');
    g.addColorStop(1, '#070e16');
    ctx.fillStyle = g;
    ctx.strokeStyle = 'rgba(255,150,80,0.45)';
    ctx.lineWidth = 1.2;
    // hull
    ctx.beginPath();
    ctx.moveTo(0, -26);
    ctx.lineTo(16, -10);
    ctx.lineTo(34, -4);
    ctx.lineTo(30, 8);
    ctx.lineTo(13, 10);
    ctx.lineTo(8, 22);
    ctx.lineTo(-8, 22);
    ctx.lineTo(-13, 10);
    ctx.lineTo(-30, 8);
    ctx.lineTo(-34, -4);
    ctx.lineTo(-16, -10);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    // turrets
    ctx.fillStyle = '#0b151f';
    for (const side of [-1, 1]) {
      ctx.beginPath();
      ctx.arc(side * 16, 0, 5, 0, TAU);
      ctx.fill();
      ctx.fillStyle = '#ff9a52';
      ctx.fillRect(side * 16 - 1.5, 4, 3, 8);
      ctx.fillStyle = '#0b151f';
    }
    // canopy
    ctx.fillStyle = 'rgba(255,120,60,0.5)';
    ctx.beginPath();
    ctx.ellipse(0, -8, 7, 5, 0, 0, TAU);
    ctx.fill();
    // lights
    ctx.globalCompositeOperation = 'lighter';
    ctx.fillStyle = '#ff5c4b';
    ctx.beginPath();
    ctx.arc(0, 12, 2, 0, TAU);
    ctx.fill();
    ctx.restore();
    return;
  } else if (e.type === 'turret') {
    const bob = Math.sin(t * 2.4 + e.seed) * 2;
    ctx.translate(0, bob);
    // fins
    ctx.fillStyle = '#182e3d';
    for (const side of [-1, 1]) {
      ctx.beginPath();
      ctx.moveTo(side * 12, -4);
      ctx.lineTo(side * 24, 14);
      ctx.lineTo(side * 10, 16);
      ctx.closePath();
      ctx.fill();
    }
    // pod
    const g = ctx.createLinearGradient(-10, 0, 12, 0);
    g.addColorStop(0, '#4b6172');
    g.addColorStop(0.4, '#243846');
    g.addColorStop(1, '#0a1620');
    ctx.fillStyle = g;
    ctx.strokeStyle = 'rgba(255,140,70,0.4)';
    ctx.lineWidth = 1;
    roundedRect(ctx, -11, -20, 22, 38, 8);
    ctx.fill();
    ctx.stroke();
    // tubes
    ctx.fillStyle = '#050b11';
    const ready = Math.max(0, Math.sin(t * 3 + e.seed));
    for (let i = 0; i < 2; i++) {
      for (let j = 0; j < 2; j++) {
        const x = -6 + i * 8;
        const y = -13 + j * 10;
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, TAU);
        ctx.fill();
        ctx.fillStyle = ready > 0.55 ? '#ff5d35' : '#4a2a22';
        ctx.beginPath();
        ctx.arc(x, y, 1.35, 0, TAU);
        ctx.fill();
        ctx.fillStyle = '#050b11';
      }
    }
    // blinking light
    ctx.globalCompositeOperation = 'lighter';
    ctx.fillStyle = `rgba(255,70,50,${0.35 + 0.5 * Math.abs(Math.sin(t * 5 + e.seed))})`;
    ctx.beginPath();
    ctx.arc(0, 23, 2.2, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

function rocketBody(ctx, w, l) {
  const g = ctx.createLinearGradient(-w / 2, 0, w / 2, 0);
  g.addColorStop(0, '#53616f');
  g.addColorStop(0.35, '#e4edf4');
  g.addColorStop(0.7, '#9aa9b7');
  g.addColorStop(1, '#3a4856');
  ctx.fillStyle = g;
  roundedRect(ctx, -w / 2, -l / 2, w, l, w / 2.6);
  ctx.fill();
  // red nose
  ctx.fillStyle = '#ff4a3a';
  ctx.beginPath();
  ctx.moveTo(-w / 2 + 1, -l / 2 + l * 0.34);
  ctx.quadraticCurveTo(0, -l / 2 - 3, w / 2 - 1, -l / 2 + l * 0.34);
  ctx.closePath();
  ctx.fill();
  // fins
  ctx.fillStyle = '#c9332a';
  for (const side of [-1, 1]) {
    ctx.beginPath();
    ctx.moveTo(side * (w / 2 - 0.5), l / 2 - 5);
    ctx.lineTo(side * (w / 2 + 5), l / 2);
    ctx.lineTo(side * (w / 2 - 0.5), l / 2);
    ctx.closePath();
    ctx.fill();
  }
  // band
  ctx.fillStyle = '#2a3743';
  ctx.fillRect(-w / 2, l * 0.12, w, 2);
}

export function drawHostile(ctx, b, t) {
  ctx.save();
  ctx.translate(b.x, b.y);
  if (b.kind === 'rocket') {
    ctx.rotate(b.angle + Math.PI / 2);
    // exhaust
    ctx.globalCompositeOperation = 'lighter';
    const fg = ctx.createLinearGradient(0, 9, 0, 28 + Math.sin(t * 40) * 4);
    fg.addColorStop(0, 'rgba(255,240,190,0.95)');
    fg.addColorStop(0.35, 'rgba(255,170,60,0.85)');
    fg.addColorStop(1, 'rgba(255,60,20,0)');
    ctx.fillStyle = fg;
    ctx.beginPath();
    ctx.moveTo(-3.5, 10);
    ctx.quadraticCurveTo(0, 24, 0, 30 + Math.sin(t * 42) * 4);
    ctx.quadraticCurveTo(0, 24, 3.5, 10);
    ctx.closePath();
    ctx.fill();
    ctx.globalCompositeOperation = 'source-over';
    rocketBody(ctx, 7, 24);
    // glow warning tip
    ctx.globalCompositeOperation = 'lighter';
    ctx.fillStyle = 'rgba(255,80,60,0.9)';
    ctx.beginPath();
    ctx.arc(0, -11, 1.8, 0, TAU);
    ctx.fill();
    ctx.globalCompositeOperation = 'source-over';
  } else if (b.kind === 'fire') {
    ctx.globalCompositeOperation = 'lighter';
    const r = b.r * 2.8;
    const g = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
    g.addColorStop(0, 'rgba(255,255,220,0.95)');
    g.addColorStop(0.25, 'rgba(255,210,90,0.85)');
    g.addColorStop(0.55, 'rgba(255,110,30,0.55)');
    g.addColorStop(1, 'rgba(255,50,10,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(0, 0, r, 0, TAU);
    ctx.fill();
    // flame tail
    const ang = Math.atan2(-b.vy, -b.vx);
    ctx.rotate(ang);
    ctx.fillStyle = 'rgba(255,150,50,0.45)';
    ctx.beginPath();
    ctx.moveTo(-b.r * 0.8, -b.r);
    ctx.quadraticCurveTo(b.r * 2.2, 0, -b.r * 0.8, b.r);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = 'rgba(255,250,220,0.9)';
    ctx.beginPath();
    ctx.arc(0, 0, b.r * 0.45, 0, TAU);
    ctx.fill();
  } else if (b.kind === 'laser') {
    ctx.globalCompositeOperation = 'lighter';
    ctx.fillStyle = 'rgba(255,60,70,0.9)';
    ctx.beginPath();
    ctx.arc(0, 0, b.r, 0, TAU);
    ctx.fill();
    ctx.fillStyle = 'rgba(255,190,190,0.9)';
    ctx.beginPath();
    ctx.arc(0, 0, b.r * 0.4, 0, TAU);
    ctx.fill();
  } else if (b.kind === 'shard') {
    ctx.globalCompositeOperation = 'lighter';
    ctx.rotate(t * 8);
    ctx.fillStyle = '#ff8a4a';
    ctx.beginPath();
    ctx.moveTo(0, -b.r * 1.6);
    ctx.lineTo(b.r, 0);
    ctx.lineTo(0, b.r * 1.6);
    ctx.lineTo(-b.r, 0);
    ctx.closePath();
    ctx.fill();
  } else {
    // plasma orb
    ctx.globalCompositeOperation = 'lighter';
    const r = b.r * 3;
    const g = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
    g.addColorStop(0, 'rgba(255,255,255,0.95)');
    g.addColorStop(0.22, b.color || 'rgba(255,90,90,0.95)');
    g.addColorStop(0.6, 'rgba(255,60,90,0.28)');
    g.addColorStop(1, 'rgba(255,40,80,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(0, 0, r, 0, TAU);
    ctx.fill();
    ctx.fillStyle = 'rgba(255,240,240,0.95)';
    ctx.beginPath();
    ctx.arc(0, 0, Math.max(1.3, b.r * 0.45), 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

export function drawFriendly(ctx, b, t) {
  ctx.save();
  ctx.translate(b.x, b.y);
  ctx.rotate(Math.atan2(b.vy, b.vx) + Math.PI / 2);
  ctx.globalCompositeOperation = 'lighter';
  const g = ctx.createRadialGradient(0, 0, 0, 0, 0, 13);
  g.addColorStop(0, 'rgba(180,255,255,0.85)');
  g.addColorStop(0.35, 'rgba(70,230,255,0.45)');
  g.addColorStop(1, 'rgba(40,150,255,0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(0, 0, 13, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#f2ffff';
  roundedRect(ctx, -2, -8, 4, 17, 2);
  ctx.fill();
  ctx.fillStyle = 'rgba(90,240,255,0.9)';
  roundedRect(ctx, -1.1, -6, 2.2, 12, 1.1);
  ctx.fill();
  ctx.restore();
}

export function drawPickup(ctx, p, t) {
  const colors = {
    power: '#5cf3ff',
    bomb: '#ffb04a',
    heart: '#ff5b78',
  };
  const letters = { power: 'P', bomb: 'B', heart: '♥' };
  const bob = Math.sin(t * 3 + p.seed) * 3;
  ctx.save();
  ctx.translate(p.x, p.y + bob);
  ctx.globalCompositeOperation = 'lighter';
  const c = colors[p.type];
  const g = ctx.createRadialGradient(0, 0, 2, 0, 0, 28);
  g.addColorStop(0, c);
  g.addColorStop(0.3, c.replace(')', ',0.35)').replace('rgb', 'rgba'));
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = c;
  ctx.globalAlpha = 0.22;
  ctx.beginPath();
  ctx.arc(0, 0, 26, 0, TAU);
  ctx.fill();
  ctx.globalAlpha = 1;
  ctx.translate(0, 0);
  ctx.rotate(Math.sin(t * 2 + p.seed) * 0.14);
  ctx.fillStyle = 'rgba(6,14,26,0.9)';
  ctx.strokeStyle = c;
  ctx.lineWidth = 1.6;
  roundedRect(ctx, -12, -12, 24, 24, 7);
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = c;
  ctx.font = 'bold 15px "Trebuchet MS", sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(letters[p.type], 0, 1);
  ctx.restore();
}

export function drawParticle(ctx, p) {
  const a = clamp(p.life / p.maxLife, 0, 1);
  if (p.type === 'smoke') {
    ctx.globalAlpha = a * 0.35;
    const r = p.size * (1.8 - a * 0.8);
    const g = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, r);
    g.addColorStop(0, p.color || 'rgba(160,170,190,0.65)');
    g.addColorStop(1, 'rgba(100,110,130,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(p.x, p.y, r, 0, TAU);
    ctx.fill();
  } else if (p.type === 'ring') {
    ctx.globalAlpha = a * 0.8;
    ctx.strokeStyle = p.color;
    ctx.lineWidth = Math.max(0.8, p.size * a * 0.35);
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.size * (1 - a) * 3.4 + p.size * 0.25, 0, TAU);
    ctx.stroke();
  } else if (p.type === 'spark') {
    ctx.globalAlpha = a;
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = p.color;
    ctx.lineWidth = p.size * 0.5;
    ctx.beginPath();
    ctx.moveTo(p.x, p.y);
    ctx.lineTo(p.x - p.vx * 0.025, p.y - p.vy * 0.025);
    ctx.stroke();
  } else if (p.type === 'debris') {
    ctx.globalAlpha = a;
    ctx.fillStyle = p.color;
    ctx.save();
    ctx.translate(p.x, p.y);
    ctx.rotate(p.rot);
    ctx.fillRect(-p.size / 2, -p.size / 4, p.size, p.size / 2);
    ctx.restore();
  } else if (p.type === 'flame') {
    ctx.globalAlpha = a * 0.85;
    ctx.globalCompositeOperation = 'lighter';
    const r = p.size * (0.6 + a);
    const g = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, r);
    g.addColorStop(0, p.color || 'rgba(255,240,190,0.9)');
    g.addColorStop(1, 'rgba(255,70,20,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(p.x, p.y, r, 0, TAU);
    ctx.fill();
  } else {
    ctx.globalAlpha = a;
    ctx.globalCompositeOperation = 'lighter';
    ctx.fillStyle = p.color;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.size * (0.4 + a * 0.6), 0, TAU);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
}

// ---------------------------------------------------------------- bosses
export function drawDragon(ctx, b, t) {
  const s = b.scale || 1;
  const flap = Math.sin(t * 2.3) * 0.12;
  const bob = Math.sin(t * 1.2) * 5;
  const charging = b.action && (b.action.name === 'breath') && b.action.stage === 'charge';
  const breathing = b.action && (b.action.name === 'breath') && b.action.stage === 'fire';
  const jawOpen = breathing ? 1 : charging ? 0.5 + Math.sin(t * 12) * 0.12 : 0.22;
  ctx.save();
  ctx.translate(b.x, b.y + bob * s);
  ctx.scale(s, s);
  if (b.flash > 0) ctx.filter = `brightness(${1 + b.flash * 1.6}) saturate(${1 - b.flash * 0.4})`;

  // aura
  ctx.globalCompositeOperation = 'lighter';
  const ag = ctx.createRadialGradient(0, 10, 30, 0, 10, 175);
  ag.addColorStop(0, 'rgba(255,90,40,0.16)');
  ag.addColorStop(0.5, 'rgba(190,30,60,0.08)');
  ag.addColorStop(1, 'rgba(120,0,40,0)');
  ctx.fillStyle = ag;
  ctx.beginPath();
  ctx.arc(0, 10, 175, 0, TAU);
  ctx.fill();
  ctx.globalCompositeOperation = 'source-over';

  // tail silhouette behind
  ctx.save();
  ctx.rotate(Math.sin(t * 1.5) * 0.05);
  ctx.fillStyle = '#2c0715';
  ctx.beginPath();
  ctx.moveTo(-18, -54);
  ctx.quadraticCurveTo(-70, -120, -26, -150);
  ctx.quadraticCurveTo(26, -150, 70, -118);
  ctx.quadraticCurveTo(20, -74, 18, -54);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(203,55,78,0.35)';
  ctx.lineWidth = 2;
  ctx.stroke();
  // tail spikes
  ctx.fillStyle = '#591027';
  for (let i = 0; i < 4; i++) {
    const px = -30 + i * 20;
    const py = -120 + Math.abs(i - 1.5) * 8;
    ctx.beginPath();
    ctx.moveTo(px - 5, py);
    ctx.lineTo(px, py - 16);
    ctx.lineTo(px + 5, py);
    ctx.closePath();
    ctx.fill();
  }
  ctx.restore();

  // wings
  for (const side of [-1, 1]) {
    ctx.save();
    ctx.translate(side * 16, -26);
    ctx.scale(side, 1);
    ctx.rotate(flap * 0.7);
    const wg = ctx.createLinearGradient(10, -50, 160, 60);
    wg.addColorStop(0, 'rgba(130,24,56,0.96)');
    wg.addColorStop(0.45, 'rgba(78,10,40,0.96)');
    wg.addColorStop(1, 'rgba(29,4,19,0.98)');
    ctx.fillStyle = wg;
    ctx.strokeStyle = 'rgba(214,62,92,0.55)';
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.moveTo(4, 0);
    ctx.bezierCurveTo(55, -80, 128, -92, 172, -42 + flap * 26);
    ctx.bezierCurveTo(146, -8, 130, 24, 120, 62 + flap * 10);
    ctx.bezierCurveTo(98, 34, 76, 18, 58, 12);
    ctx.bezierCurveTo(36, 30, 20, 26, 4, 0);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    // membrane lines
    ctx.strokeStyle = 'rgba(236,109,130,0.28)';
    ctx.lineWidth = 1.2;
    for (const [x, y] of [[118, -30], [96, 10], [60, -18]]) {
      ctx.beginPath();
      ctx.moveTo(8, -2);
      ctx.quadraticCurveTo(x * 0.6, y * 0.6, x, y);
      ctx.stroke();
    }
    // wing claw
    ctx.fillStyle = '#e7c7a6';
    ctx.beginPath();
    ctx.moveTo(170, -42 + flap * 26);
    ctx.lineTo(184, -53 + flap * 26);
    ctx.lineTo(174, -34 + flap * 26);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  // body
  const bodyG = ctx.createRadialGradient(-12, -22, 4, 0, 0, 76);
  bodyG.addColorStop(0, '#a32644');
  bodyG.addColorStop(0.55, '#63102d');
  bodyG.addColorStop(1, '#260511');
  ctx.fillStyle = bodyG;
  ctx.beginPath();
  ctx.ellipse(0, -6, 46, 62, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(219,79,102,0.4)';
  ctx.lineWidth = 1.4;
  ctx.stroke();

  // belly plates
  ctx.save();
  ctx.globalAlpha = 0.8;
  for (let i = 0; i < 4; i++) {
    ctx.fillStyle = i % 2 ? 'rgba(255,139,74,0.22)' : 'rgba(255,180,90,0.32)';
    ctx.beginPath();
    ctx.ellipse(0, 4 + i * 12, 26 - i * 3.5, 5.5, 0, 0, TAU);
    ctx.fill();
  }
  ctx.restore();

  // neck spikes
  ctx.fillStyle = '#4a0a24';
  for (let i = 0; i < 4; i++) {
    const side = i % 2 === 0 ? -1 : 1;
    const y = -32 + Math.floor(i / 2) * 15;
    ctx.beginPath();
    ctx.moveTo(side * 40, y);
    ctx.lineTo(side * 55, y - 9);
    ctx.lineTo(side * 42, y + 5);
    ctx.closePath();
    ctx.fill();
  }

  // head
  const headG = ctx.createLinearGradient(0, -64, 0, 54);
  headG.addColorStop(0, '#b2324c');
  headG.addColorStop(0.45, '#7d1633');
  headG.addColorStop(1, '#330a19');
  ctx.fillStyle = headG;
  ctx.strokeStyle = 'rgba(255,131,131,0.5)';
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.moveTo(0, -62);
  ctx.bezierCurveTo(28, -62, 45, -48, 48, -20);
  ctx.bezierCurveTo(52, 12, 36, 38, 23, 43);
  ctx.bezierCurveTo(8, 50, -8, 50, -23, 43);
  ctx.bezierCurveTo(-36, 38, -52, 12, -48, -20);
  ctx.bezierCurveTo(-45, -48, -28, -62, 0, -62);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();

  // forehead plate
  const fg = ctx.createLinearGradient(0, -60, 0, -6);
  fg.addColorStop(0, 'rgba(230,95,105,0.55)');
  fg.addColorStop(1, 'rgba(84,9,31,0.1)');
  ctx.fillStyle = fg;
  ctx.beginPath();
  ctx.moveTo(0, -58);
  ctx.quadraticCurveTo(24, -52, 26, -16);
  ctx.quadraticCurveTo(13, 8, 0, 12);
  ctx.quadraticCurveTo(-13, 8, -26, -16);
  ctx.quadraticCurveTo(-24, -52, 0, -58);
  ctx.closePath();
  ctx.fill();

  // horns
