  ctx.globalCompositeOperation = 'source-over';

  // legs
  ctx.fillStyle = '#111b26';
  ctx.strokeStyle = 'rgba(120,170,200,0.28)';
  ctx.lineWidth = 1.3;
  for (const side of [-1, 1]) {
    ctx.beginPath();
