    pg.addColorStop(1, '#0b141d');
    ctx.fillStyle = pg;
    ctx.strokeStyle = 'rgba(150,200,225,0.3)';
    ctx.lineWidth = 1.3;
    roundedRect(ctx, -27, -24, 54, 46, 9);
    ctx.fill();
    ctx.stroke();
    // tubes
    for (let i = 0; i < 3; i++) {
      const tx = -14 + i * 14;
      ctx.fillStyle = '#05090e';
      ctx.beginPath();
