  ctx.lineTo(-48, 22);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = 'rgba(0,0,0,0.22)';
  ctx.beginPath();
  ctx.moveTo(38, -56);
  ctx.lineTo(0, -50);
  ctx.lineTo(0, 20);
  ctx.lineTo(30, 48);
  ctx.lineTo(48, 22);
  ctx.closePath();
  ctx.fill();

  // chest vents
  ctx.fillStyle = '#050a0f';
  for (const side of [-1, 1]) {
